-- JSON_SCHEMA_VALID tests
SELECT JSON_SCHEMA_VALID('{"type":"object","required":["a"]}', '{"a":1}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","required":["a"]}', '{}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","properties":{"a":{"type":"integer"}}}', '{"a":2}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","properties":{"a":{"type":"integer"}}}', '{"a":1.5}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","properties":{"a":{"type":"integer"}}}', '{"a":"1"}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"array","items":{"type":"string"}}', '["a","b"]') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"array","items":{"type":"string"}}', '["a",2]') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"array","minItems":1,"maxItems":2}', '[]') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"array","uniqueItems":true}', '[1,1]') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"string","minLength":2,"maxLength":3}', '"abcd"') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"string","pattern":"^a"}', '"abc"') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"string","pattern":"^a"}', '"bcd"') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"number","minimum":5}', '5') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"number","minimum":5,"exclusiveMinimum":true}', '5') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"number","minimum":5,"exclusiveMinimum":true}', '6') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"number","maximum":5}', '6') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"number","multipleOf":2}', '5') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"enum":[1,"a",null]}', '"a"') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"enum":[1,"a",null]}', '2') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":["string","null"]}', 'null') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","additionalProperties":false,"properties":{"a":{"type":"number"}}}', '{"a":1,"z":1}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"allOf":[{"type":"number"},{"minimum":1}]}', '0') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"anyOf":[{"type":"string"},{"type":"number"}]}', 'true') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"oneOf":[{"type":"number"},{"minimum":1}]}', '5') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"not":{"type":"string"}}', '"a"') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"definitions":{"p":{"type":"number"}},"properties":{"a":{"$ref":"#/definitions/p"}}}', '{"a":1}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"format":"email"}', '"abc"') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","required":["a"]}', NULL) AS is_valid;
SELECT JSON_SCHEMA_VALID(NULL, '{}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object"}', CAST('{"a":1}' AS JSON)) AS is_valid;
SELECT JSON_SCHEMA_VALID(CAST('{"type":"integer"}' AS JSON), '5') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object"}', 'not json') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object"}', 5) AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","required":["a","b"],"properties":{"a":{"type":"number"},"b":{"type":"string"}}}', '{"a":"x","b":3}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","required":["a","b"],"properties":{"a":{"type":"number"},"b":{"type":"string"}}}', '{"a":1,"b":"ok"}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","required":["c"],"properties":{"a":{"type":"number"}},"additionalProperties":false}', '{"a":"x","z":1}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"string","minLength":5,"pattern":"^[0-9]+$"}', '"ab"') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"string","minLength":2,"pattern":"^[0-9]+$"}', '"12"') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"number","minimum":10,"maximum":5}', '7') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"array","minItems":3,"maxItems":1,"items":{"type":"string"},"uniqueItems":true}', '[1,1]') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","minProperties":2,"maxProperties":1}', '{}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"allOf":[{"type":"number"},{"minimum":1}],"not":{"enum":[5]}}', '5') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"allOf":[{"type":"number"},{"minimum":1}],"not":{"enum":[5]}}', '6') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"anyOf":[{"type":"string"},{"type":"boolean"}],"allOf":[{"minLength":3}]}', '1') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"oneOf":[{"type":"number"},{"minimum":1}],"maxLength":2}', '"abc"') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"oneOf":[{"type":"number"},{"minimum":1}],"maxLength":2}', '5') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","properties":{"user":{"type":"object","required":["name","age"],"properties":{"name":{"type":"string","minLength":1},"age":{"type":"integer","minimum":0}}}}}', '{"user":{"name":"","age":-1}}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","properties":{"user":{"type":"object","required":["name","age"],"properties":{"name":{"type":"string","minLength":1},"age":{"type":"integer","minimum":0}}}}}', '{"user":{"name":"bob","age":2}}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"array","items":{"type":"object","required":["id"],"properties":{"id":{"type":"number"},"tags":{"type":"array"}}}}', '[{"id":"x"},{"id":1,"tags":"no"}]') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"array","items":{"type":"object","required":["id"],"properties":{"id":{"type":"number"}}}}', '[{"id":1},{"id":2}]') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","properties":{"a":{"type":"number"}},"required":["a"],"additionalProperties":{"type":"string"}}', '{"a":"x","b":2}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","properties":{"a":{"type":"number"}},"required":["a"],"additionalProperties":{"type":"string"}}', '{"a":1,"b":"two"}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","patternProperties":{"^x":{"type":"number"}},"additionalProperties":false}', '{"xa":"s","y":1}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","patternProperties":{"^x":{"type":"number"}},"additionalProperties":false}', '{"xa":1}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","dependencies":{"a":["b"]},"properties":{"b":{"type":"number"}}}', '{"a":1,"b":"s"}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","dependencies":{"a":["b"]},"properties":{"b":{"type":"number"}}}', '{"b":2}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","dependencies":{"a":["b"]},"properties":{"b":{"type":"number"}}}', '{"a":1}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"string","enum":["a","b"],"maxLength":0}', '"c"') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":["integer","null"],"minimum":0}', 'null') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":["integer","null"],"minimum":0}', '-1') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","properties":{"a":{"type":"object","properties":{"b":{"type":"array","items":{"type":"number","maximum":3}}}}}}', '{"a":{"b":[1,5,"x"]}}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","properties":{"a":{"type":"object","properties":{"b":{"type":"array","items":{"type":"number","maximum":3}}}}}}', '{"a":{"b":[1,3]}}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","required":["x"],"properties":{"a":{"type":"number"}},"minProperties":3}', '{"a":"s"}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","properties":{"a":{"type":"number"}}}', '{"a":1,"b":"x","c":[]}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","required":["a"],"properties":{"a":{"type":"number","minimum":1}},"not":{"required":["b"]}}', '{"a":0,"b":1}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","required":["a"],"properties":{"a":{"type":"number","minimum":1}},"not":{"required":["b"]}}', '{"a":2}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","properties":{"a":{"type":"string"}},"const":{"a":"x"}}', '{"a":"y"}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"object","properties":{"a":{"type":"string"}},"propertyNames":{"maxLength":1}}', '{"ab":"y"}') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"array","contains":{"type":"number"}}', '["a","b"]') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"type":"number","exclusiveMaximum":5}', '5') AS is_valid;
SELECT JSON_SCHEMA_VALID('{"if":{"type":"string"},"then":{"minLength":3},"type":"string"}', '"ab"') AS is_valid;
